 FullState full;ComboBox presetBox;bool presetLoading;TextBlock editingStatus,appliedStatus;StackPanel fullBar;Button trialButton;ContextMenu presetActions;Expander tuningExpander;TextBox recordName;string recordingName,recordingPreset;int recordingSide;string trialName,trialId;bool fullTrial,resumeAfterTrial;PadBook trialSnapshot;
