 static T Clone<T>(T x){var j=new JavaScriptSerializer{MaxJsonLength=8388608};return j.Deserialize<T>(j.Serialize(x));}
 static void ValidatePresetName(string n){if(string.IsNullOrWhiteSpace(n) || n.Trim().Length>60 || n.Contains("\n") || n.Contains("\r"))throw new Exception(L.T("名称请输入 1–60 字。"));}
