 void ValidateFull(FullState s){if(s==null || s.Version!=2 || s.Presets==null || s.Presets.Count==0 || s.Presets.Count>200 || s.Drafts==null)throw new Exception(L.T("不支持的配置文件。"));var ids=new HashSet<string>();foreach(var p in s.Presets){ValidatePresetName(p.Name);if(string.IsNullOrEmpty(p.Id) || !ids.Add(p.Id))throw new Exception(L.T("配置标识无效。"));p.Pads.Validate();}if(!ids.Contains(s.EditingId))throw new Exception(L.T("编辑配置缺失。"));if(s.Applied!=null)s.Applied.Validate();if(s.Apps==null)s.Apps=new List<AppAssignment>();new RuntimeProfiles{Apps=s.Apps}.Validate();foreach(var app in s.Apps)if(!ids.Contains(app.PresetId))throw new Exception(L.T("应用所属配置缺失。"));if(s.GlobalEditingId!=null && !ids.Contains(s.GlobalEditingId))throw new Exception(L.T("全局编辑配置缺失。"));foreach(var x in s.Drafts){if(!ids.Contains(x.Key))throw new Exception(L.T("草稿所属配置缺失。"));x.Value.Validate();}}
 FullPreset AddFull(string name,PadBook book){ValidatePresetName(name);string n=name.Trim();int i=2;while(full.Presets.Exists(x=>x.Name==n))n=name.Trim()+" ("+(i++)+")";var p=new FullPreset{Id=Guid.NewGuid().ToString("N"),Name=n,Pads=Clone(book)};full.Presets.Add(p);return p;}
 static PadBook SteamlessPreset(PadBook source){var b=Clone(source);foreach(var p in new[]{b.Left,b.Right}){if(p.Action=="mouse"){p.Speed=.01125;p.Smooth=0;p.Inertia=false;p.StableMs=0;p.DragScale=1;}if(p.Action=="scroll"){p.FineScroll=true;p.ScrollUnits=6000;}p.SteamlessHaptics=true;p.TouchGraceMs=48;p.ReleaseGraceMs=180;p.MotionPressureLimit=900;p.Interval=50;p.Spacing=130;p.Motion=new WaveSpec{Kind="command",Command=1,Gain=0,Source="SteamlessController · TICK"};p.PressWave=new WaveSpec{Kind="command",Command=2,Gain=0,Source="SteamlessController · CLICK"};p.ReleaseWave=new WaveSpec{Kind="command",Command=2,Gain=0,Source="SteamlessController · RELEASE"};}b.Validate();return b;}
