 void LoadFull(){if(File.Exists(LibraryPath)){if(new FileInfo(LibraryPath).Length>8388608)throw new Exception(L.T("配置文件过大。"));full=new JavaScriptSerializer{MaxJsonLength=8388608}.Deserialize<FullState>(File.ReadAllText(LibraryPath));ValidateFull(full);editingAppPath=full.Apps.Any(a=>string.Equals(a.Path,full.EditingAppPath,StringComparison.OrdinalIgnoreCase))?full.EditingAppPath:null;if(editingAppPath==null && full.GlobalEditingId!=null)full.EditingId=full.GlobalEditingId;padBook=Clone(full.Drafts.ContainsKey(full.EditingId)?full.Drafts[full.EditingId]:ActivePreset().Pads);return;}full=new FullState();var initial=AddFull(L.T("我的控制器配置"),padBook);full.EditingId=initial.Id;full.AppliedId=initial.Id;full.AppliedName=initial.Name;full.Applied=Clone(initial.Pads);string legacy=System.IO.Path.Combine(AppPaths.Data,"profiles","haptics-library.json");if(File.Exists(legacy)){var rows=new JavaScriptSerializer().Deserialize<List<LegacyHaptic>>(File.ReadAllText(legacy));if(rows!=null)foreach(var old in rows){var b=Clone(padBook);foreach(var p in new[]{b.Left,b.Right}){p.Motion=Clone(old.Motion);p.PressWave=Clone(old.Press);p.Interval=old.Interval;p.Spacing=old.Spacing;}b.Validate();AddFull(L.T("旧触觉 · ")+old.Name,b);}}}
