 void BuildPresetLibrary(StackPanel haptic,Expander recording,StackPanel capture){LoadFull();EnsureSteamlessPreset();EnsureStarterPresets();var page=Get<StackPanel>("TouchPage");var head=new StackPanel{Margin=new Thickness(0,0,0,16)};var grid=new Grid();grid.ColumnDefinitions.Add(new ColumnDefinition());grid.ColumnDefinitions.Add(new ColumnDefinition{Width=GridLength.Auto});head.Children.Add(grid);presetBox=new ComboBox{Padding=new Thickness(9)};grid.Children.Add(presetBox);var more=new Button{Content="•••",ToolTip=L.T("整份配置选项"),Margin=new Thickness(8,0,0,0),Padding=new Thickness(16,8,16,8)};grid.Children.Add(more);Grid.SetColumn(more,1);presetActions=ActionMenu();more.Click+=delegate{presetActions.PlacementTarget=more;presetActions.IsOpen=true;};editingStatus=Hint(head,"");page.Children.Insert(0,head);MenuAction(presetActions,L.T("新建配置…"),delegate{ReadEditor();string name=AskName(L.T("新建配置"),ActivePreset().Name+L.T(" · 副本"));if(name==null)return;CreateFromCurrent(name);Notice(L.T("已基于当前编辑内容新建配置，尚未应用。"));});MenuAction(presetActions,L.T("改名…"),delegate{string name=AskName(L.T("配置改名"),ActivePreset().Name);if(name==null)return;ValidatePresetName(name);if(full.Presets.Exists(x=>x.Id!=full.EditingId && x.Name==name))throw new Exception(L.T("已有同名配置。"));ActivePreset().Name=name;if(full.AppliedId==full.EditingId)full.AppliedName=name;SaveLibrary();SyncPresetChoice();});MenuAction(presetActions,L.T("删除配置"),delegate{if(recorder!=null)throw new Exception(L.T("录制期间不能删除配置。"));if(fullTrial && trialId==full.EditingId)throw new Exception(L.T("请先结束此配置的试用再删除。"));if(full.Apps.Any(a=>a.PresetId==full.EditingId))throw new Exception(L.T("此配置仍关联应用或全局编辑，请先选择另一份配置。"));if(full.EditingId==full.AppliedId)throw new Exception(L.T("此配置正在使用或待接管，请先应用另一份配置再删除。"));if(full.Presets.Count==1)throw new Exception(L.T("至少保留一份配置。"));string id=full.EditingId;full.Presets.Remove(ActivePreset());full.Drafts.Remove(id);full.EditingId=full.Presets[0].Id;if(editingAppPath==null)full.GlobalEditingId=full.EditingId;padBook=Clone(full.Drafts.ContainsKey(full.EditingId)?full.Drafts[full.EditingId]:ActivePreset().Pads);LoadPad();SavePads();});MenuAction(presetActions,L.T("分享当前配置…"),SharePreset);MenuAction(presetActions,L.T("备份全部配置（含应用路径）…"),delegate{ReadEditor();var d=new Microsoft.Win32.SaveFileDialog{Filter=L.T("控制器配置备份|*.json"),FileName=L.T("SC2-控制器配置备份.json")};if(d.ShowDialog(window)==true){full.Drafts[full.EditingId]=Clone(padBook);AtomicWrite(d.FileName,new JavaScriptSerializer{MaxJsonLength=8388608}.Serialize(full));}});MenuAction(presetActions,L.T("导入配置…"),delegate{var d=new Microsoft.Win32.OpenFileDialog{Filter=L.T("控制器配置备份|*.json")};if(d.ShowDialog(window)!=true)return;if(new FileInfo(d.FileName).Length>8388608)throw new Exception(L.T("备份过大。"));var source=new JavaScriptSerializer{MaxJsonLength=8388608}.Deserialize<FullState>(File.ReadAllText(d.FileName));ValidateFull(source);if(source.Presets.Count+full.Presets.Count>200)throw new Exception(L.T("配置总数超过 200。"));var ids=new Dictionary<string,string>();foreach(var p in source.Presets){var n=AddFull(p.Name,p.Pads);ids[p.Id]=n.Id;if(source.Drafts.ContainsKey(p.Id))full.Drafts[n.Id]=Clone(source.Drafts[p.Id]);}foreach(var a in source.Apps)if(!full.Apps.Any(x=>string.Equals(x.Path,a.Path,StringComparison.OrdinalIgnoreCase)))full.Apps.Add(new AppAssignment{Path=a.Path,PresetId=ids[a.PresetId]});SaveLibrary();SyncPresetChoice();RefreshApps();SyncScope();Notice(L.T("已导入配置和应用关联。导入的应用先使用全局，单独配置需点击应用；现有应用保持不变。"));});
 var tuning=new StackPanel();var elements=haptic.Children.Cast<UIElement>().Where(x=>x!=haptic.Children[0] && x!=recording).ToList();foreach(var e in elements){haptic.Children.Remove(e);tuning.Children.Add(e);}tuningExpander=new Expander{Header=L.T("微调"),Content=tuning,Foreground=Brushes.LightGray};haptic.Children.Add(tuningExpander);recording.Header=L.T("录制触觉");recordName=new TextBox{Text=L.T("本次触觉录制")};Hint(capture,L.T("录制只修改所选侧的触觉草稿；整体试用、应用和保存位于固定底栏。"));Btn(capture,L.T("载入上次录制"),CreateRecordedPreset);
 fullBar=Get<StackPanel>("FullConfigBar");appliedStatus=Hint(fullBar,"");var actions=new WrapPanel();fullBar.Children.Add(actions);trialButton=Btn(actions,L.T("试用整份配置"),StartFullTrial);Btn(actions,L.T("应用"),ApplyFull);Btn(actions,L.T("还原"),RestoreSaved);Btn(actions,L.T("保存"),SaveActivePreset);Btn(actions,L.T("另存为…"),SaveAsFull);
 presetBox.SelectionChanged+=delegate{if(presetLoading)return;var next=presetBox.SelectedItem as FullPreset;if(next==null)return;try{ReadEditor();full.Drafts[full.EditingId]=Clone(padBook);full.EditingId=next.Id;padBook=Clone(full.Drafts.ContainsKey(next.Id)?full.Drafts[next.Id]:next.Pads);LoadPad();SavePads();}catch(Exception e){SyncPresetChoice();Notice(e.Message);}};SyncPresetChoice();}
 void CompactFiles(StackPanel page,StackPanel files){var border=files.Parent as Border;if(border!=null)page.Children.Remove(border);}
 Candidate BestRecorded(string role,WaveSpec current){Candidate best=null;foreach(Candidate c in candidateBox.Items){if(role=="motion"?(c.Phase!="fast_slide" && c.Phase!="slow_slide"):c.Phase!=role)continue;if(best==null || (c.Wave.Kind==current.Kind && best.Wave.Kind!=current.Kind) || (c.Wave.Kind==best.Wave.Kind && c.Count>best.Count))best=c;}return best;}
 void CreateRecordedPreset(){if(candidateBox.Items.Count==0)throw new Exception(L.T("没有足够干净的录制样本，原配置保留。"));string id=recorder==null?full.EditingId:recordingPreset;int side=recorder==null?editedSide:recordingSide;PadBook book=id==full.EditingId?padBook:full.Drafts[id];var p=side==0?book.Left:book.Right;var motion=BestRecorded("motion",p.Motion);var press=BestRecorded("press",p.PressWave);var release=BestRecorded("release",p.ReleaseWave);var updated=new List<string>();var retained=new List<string>();if(motion!=null){p.Motion=Clone(motion.Wave);updated.Add(L.T("滑动"));}else retained.Add(L.T("滑动"));if(press!=null){p.PressWave=Clone(press.Wave);updated.Add(L.T("按下"));}else retained.Add(L.T("按下"));if(release!=null){p.ReleaseWave=Clone(release.Wave);updated.Add(L.T("松开"));}else retained.Add(L.T("松开"));if(id==full.EditingId)LoadPad();SavePads();recordStatus.Text=L.T("已更新")+(side==0?L.T("左板"):L.T("右板"))+"："+string.Join("、",updated.ToArray())+"。"+(retained.Count>0?L.T("样本不足，保留原值：")+string.Join("、",retained.ToArray())+"。":"")+L.T("速度、按键、防误触和触发节奏保留；尚未应用或保存。");}
 void TestRecordingMerge(){padBook=SteamlessPreset(new PadBook());padBook.KeyboardButton="R4";padBook.Left.Speed=.031;padBook.Left.TouchGraceMs=73;padBook.Left.Interval=81;padBook.Left.Spacing=155;var before=Clone(padBook);LoadPad();candidateBox.Items.Clear();candidateBox.Items.Add(new Candidate{Phase="fast_slide",Count=12,Wave=new WaveSpec{Kind="command",Command=1,Gain=-6}});candidateBox.Items.Add(new Candidate{Phase="press",Count=7,Wave=new WaveSpec{Kind="command",Command=2,Gain=-9}});CreateRecordedPreset();if(padBook.Left.Motion.Gain!=-6 || padBook.Left.PressWave.Gain!=-9 || padBook.Left.ReleaseWave.Gain!=before.Left.ReleaseWave.Gain || padBook.Right.Motion.Gain!=before.Right.Motion.Gain || padBook.KeyboardButton!="R4" || padBook.Left.TouchGraceMs!=73 || padBook.Left.Interval!=81 || padBook.Left.Spacing!=155 || Math.Abs(padBook.Left.Speed-.031)>.000001)throw new Exception("Recording overwrote base profile or opposite pad");}
 void TestPresets(){var original=Clone(full.Applied);var active=ActivePreset();var saved=Clone(active.Pads);padBook.Left.Speed=.07;padBook.Right.Motion.OnUs=810;LoadPad();ReadEditor();if(CommittedPads().Json()!=original.Json() || active.Pads.Json()!=saved.Json())throw new Exception("Draft leaks into applied/saved");SaveActivePreset();if(active.Pads.Right.Motion.OnUs!=810 || active.Pads.Left.Speed!=.07 || CommittedPads().Json()!=original.Json())throw new Exception("Whole config save isolation");padBook.Right.Motion.OnUs=930;LoadPad();RestoreSaved();if(padBook.Right.Motion.OnUs!=810)throw new Exception("Restore failed");var copy=AddFull(L.T("副本"),padBook);copy.Pads.Left.Speed=.09;if(active.Pads.Left.Speed!=.07)throw new Exception("Save as aliases original");var roundtrip=Clone(full);ValidateFull(roundtrip);var draft=padBook.Json();string applied=CommittedPads().Json();CreateFromCurrent(L.T("新建测试"));if(padBook.Json()!=draft || ActivePreset().Pads.Json()!=draft || CommittedPads().Json()!=applied)throw new Exception("New preset replaced current tuning or applied it");}
 void MenuAction(ContextMenu menu,string label,Action action){var item=new MenuItem{Style=window.FindResource(typeof(MenuItem)) as Style,Header=label,Padding=new Thickness(14,9,14,9)};item.Click+=delegate{Guard(action);};menu.Items.Add(item);}
 ContextMenu ActionMenu(){return new ContextMenu{Template=window.FindResource("CleanMenu") as ControlTemplate,Background=new SolidColorBrush(Color.FromRgb(28,43,56)),Foreground=Brushes.White,BorderBrush=new SolidColorBrush(Color.FromRgb(54,78,96)),Padding=new Thickness(5)};}
 string AskName(string title,string initial){var content=new StackPanel{Margin=new Thickness(24)};var dialog=new Window{Title=title,Owner=window,Width=420,SizeToContent=SizeToContent.Height,ResizeMode=ResizeMode.NoResize,WindowStartupLocation=WindowStartupLocation.CenterOwner,Background=new SolidColorBrush(Color.FromRgb(24,36,48)),Foreground=Brushes.White,Content=content,FontFamily=window.FontFamily};content.Children.Add(new TextBlock{Text=title,FontSize=20,Margin=new Thickness(0,0,0,18)});var input=new TextBox{Text=initial,Padding=new Thickness(10),Background=new SolidColorBrush(Color.FromRgb(15,26,36)),Foreground=Brushes.White,MaxLength=60};content.Children.Add(input);var buttons=new StackPanel{Orientation=Orientation.Horizontal,HorizontalAlignment=HorizontalAlignment.Right,Margin=new Thickness(0,18,0,0)};content.Children.Add(buttons);var cancel=new Button{Content=L.T("取消"),Padding=new Thickness(18,8,18,8),Margin=new Thickness(0,0,8,0),IsCancel=true};buttons.Children.Add(cancel);var ok=new Button{Content=L.T("保存"),Padding=new Thickness(18,8,18,8),IsDefault=true};buttons.Children.Add(ok);ok.Click+=delegate{if(!string.IsNullOrWhiteSpace(input.Text))dialog.DialogResult=true;};dialog.Loaded+=delegate{input.Focus();input.SelectAll();};return dialog.ShowDialog()==true?input.Text.Trim():null;}
